  "m_your_phone_denied_the_request_a36e4c8292": "Your phone denied the request without asking you — Android restricts SMS access for apps installed outside the Play Store.\n\nTo unlock it:\n1. Open AvaTOK’s App info page\n2. Tap the ⋮ menu → “Allow restricted settings”\n3. Come back and tap Enable again\n\nIf Android has stopped asking, pick AvaTOK directly under Default apps → SMS app.",
