  "m_your_phone_won_t_let_b6fa552e24": "Your phone won't let AvaTOK do this quietly in the background, so your phone app will open with the code {value1} filled in. That code is the standard, safe instruction phone companies worldwide use to switch on call forwarding — it only talks to your phone company and can't read or change anything on your phone.",
